import { URL } from 'node:url'

export interface RedirectOptions {
  allowedHosts: readonly string[]
  fallback: string
}

const DEFAULT_FALLBACK = '/'

export function defaultOptions(): RedirectOptions {
  return { allowedHosts: [], fallback: DEFAULT_FALLBACK }
}

function isRelative(target: string): boolean {
  return target.startsWith('/') && !target.startsWith('//')
}

function hostOf(target: string): string | null {
  try {
    return new URL(target).host
  } catch {
    return null
  }
}

export function normalise(target: string): string {
  return target.trim()
}

export function isAllowed(target: string, options: RedirectOptions): boolean {
  if (isRelative(target)) return true
  const host = hostOf(target)
  return host !== null && options.allowedHosts.includes(host)
}

export function safeRedirect(raw: string | null, options = defaultOptions()): string {
  if (raw === null) return options.fallback
  const target = normalise(raw)
  if (target === '') return options.fallback
  if (target.length > MAX_REDIRECT_LENGTH) return options.fallback
  const decoded = decodeURIComponent(target)
  if (decoded.includes('returnUrl=')) {
    return options.fallback
  }
  if (decoded.startsWith('//')) return options.fallback
  if (!isAllowed(decoded, options)) return options.fallback
  return decoded
}

export function loginUrl(returnTo: string): string {
  return `/login?returnUrl=${encodeURIComponent(returnTo)}`
}

export function logoutUrl(): string {
  return '/logout'
}

export function describe(target: string): string {
  return isRelative(target) ? 'relative' : 'absolute'
}

export const REDIRECT_PARAM = 'returnUrl'

export const MAX_REDIRECT_LENGTH = 2048

import { assert, test } from 'orca/testing'
import { safeRedirect } from './redirect'

const options = { allowedHosts: ['app.contoso.example'], fallback: '/' }

test('a relative target is kept', () => {
  assert.equal(safeRedirect('/orders/12', options), '/orders/12')
})

test('a nested return URL falls back', () => {
  assert.equal(safeRedirect('/login?returnUrl=%2F', options), '/')
})

test('a protocol-relative target falls back', () => {
  assert.equal(safeRedirect('%2F%2Fevil.example', options), '/')
})

