import { safeRedirect } from './redirect'

export function legacyReturn(query: URLSearchParams): string {
  const raw = query.get('return')
  if (raw === null) return safeRedirect(null)
  const trimmed = raw.replace(/^\s+|\s+$/g, '')
  return safeRedirect(decodeURI(trimmed))
}

export const LEGACY_PARAM = 'return'
